import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Banner,
  Box,
  Divider,
  InlineGrid,
  ProgressBar,
  List,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan } from "../lib/plans";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  const d = typeof date === "string" ? new Date(date) : date;
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

  const [
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    subscription,
    recentCharts,
    widgetConfig,
    recommenderConfig,
    assignmentCount,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.sizeChart.count({ where: { shop, status: "draft" } }),
    db.analyticsEvent.count({
      where: { shop, eventType: "view", createdAt: { gte: thirtyDaysAgo } },
    }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend" } }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: {
        id: true,
        name: true,
        category: true,
        status: true,
        updatedAt: true,
        _count: { select: { assignments: true } },
      },
    }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  const hasChart = chartCount > 0;
  const hasAssignment = assignmentCount > 0;
  const hasWidget = widgetConfig !== null;
  const hasRecommender =
    recommenderConfig !== null && recommenderConfig.enabled;

  const setupSteps = [
    {
      key: "create-chart",
      title: "Create your first size chart",
      description:
        "Choose from 9 ready-made templates or build a custom chart from scratch.",
      done: hasChart,
      actionLabel: "Create chart",
      actionUrl: "/app/size-charts",
    },
    {
      key: "customize-widget",
      title: "Style your size chart widget",
      description:
        "Customize colors, layout, and text to match your store's brand.",
      done: hasWidget,
      actionLabel: "Go to Appearance",
      actionUrl: "/app/widget",
    },
    {
      key: "assign-products",
      title: "Assign chart to products",
      description:
        "Link your chart to products, collections, or tags so it shows automatically.",
      done: hasAssignment,
      actionLabel: "Assign products",
      actionUrl: "/app/size-charts",
    },
  ];

  const completedCount = setupSteps.filter((s) => s.done).length;

  return {
    shop,
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts: recentCharts.map((c) => ({
      ...c,
      assignmentCount: c._count.assignments,
      updatedAt: c.updatedAt.toISOString(),
    })),
    hasRecommender,
    setupSteps,
    completedCount,
    totalSteps: setupSteps.length,
  };
};

// ---------------------------------------------------------------------------
// Step circle sub-component (custom visual — no Polaris equivalent)
// ---------------------------------------------------------------------------

function StepCircle({ done }: { done: boolean }) {
  return (
    <div
      style={{
        width: "22px",
        height: "22px",
        borderRadius: "50%",
        border: done ? "none" : "2px solid #c9cccf",
        background: done ? "#1a73e8" : "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        marginTop: "1px",
        color: "#fff",
        fontSize: "12px",
        fontWeight: 700,
      }}
    >
      {done && "✓"}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function Dashboard() {
  const {
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts,
    setupSteps,
    completedCount,
    totalSteps,
  } = useLoaderData<typeof loader>();

  const [setupOpen, setSetupOpen] = useState(true);
  const [expandedStep, setExpandedStep] = useState<string | null>(
    setupSteps.find((s) => !s.done)?.key ?? null,
  );

  const isSetupComplete = completedCount === totalSteps;
  const isFreePlan = plan.id === "free";
  const maxCharts = plan.limits.maxCharts;
  const setupProgressPct = Math.round((completedCount / totalSteps) * 100);
  const chartUsagePct =
    maxCharts > 0 ? Math.round((chartCount / maxCharts) * 100) : 0;

  return (
    <Page
      title="Dashboard"
      primaryAction={{ content: "Create Size Chart", url: "/app/size-charts" }}
    >
      <Layout>
        {/* ================================================================ */}
        {/* SETUP GUIDE — collapsible, prominent                              */}
        {/* ================================================================ */}
        {!isSetupComplete && (
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                {/* Header row */}
                <InlineStack align="space-between" blockAlign="center">
                  <BlockStack gap="100">
                    <Text as="h2" variant="headingMd" fontWeight="bold">
                      Setup guide
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Use this personalized guide to get you started with Size
                      Chart &amp; Recommender.
                    </Text>
                  </BlockStack>
                  <Button onClick={() => setSetupOpen(!setupOpen)}>
                    {setupOpen ? "Hide" : "Show"}
                  </Button>
                </InlineStack>

                {/* Progress */}
                <BlockStack gap="100">
                  <Text as="p" variant="bodyMd" tone="subdued">
                    {completedCount} of {totalSteps} steps completed
                  </Text>
                  <ProgressBar
                    progress={setupProgressPct}
                    tone="highlight"
                    size="small"
                  />
                </BlockStack>

                {/* Steps */}
                {setupOpen && (
                  <BlockStack gap="200">
                    {setupSteps.map((step) => (
                      <Box
                        key={step.key}
                        padding="400"
                        borderWidth="025"
                        borderColor="border"
                        borderRadius="200"
                      >
                        <div
                          onClick={() =>
                            setExpandedStep(
                              expandedStep === step.key ? null : step.key,
                            )
                          }
                          style={{ cursor: "pointer" }}
                        >
                          <InlineStack gap="400" blockAlign="start">
                            <StepCircle done={step.done} />
                            <BlockStack gap="100">
                              <Text
                                as="p"
                                variant="bodyMd"
                                tone={step.done ? "subdued" : undefined}
                                textDecorationLine={
                                  step.done ? "line-through" : undefined
                                }
                              >
                                {step.title}
                              </Text>

                              {expandedStep === step.key && !step.done && (
                                <BlockStack gap="300">
                                  <Text as="p" variant="bodyMd" tone="subdued">
                                    {step.description}
                                  </Text>
                                  <Button
                                    variant="primary"
                                    url={step.actionUrl}
                                  >
                                    {step.actionLabel}
                                  </Button>
                                </BlockStack>
                              )}
                            </BlockStack>
                          </InlineStack>
                        </div>
                      </Box>
                    ))}
                  </BlockStack>
                )}
              </BlockStack>
            </Card>
          </Layout.Section>
        )}

        {/* ================================================================ */}
        {/* STATS OVERVIEW                                                    */}
        {/* ================================================================ */}
        <Layout.Section>
          <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
            <Card>
              <BlockStack gap="100">
                <Text as="h2" variant="headingXl" fontWeight="bold">
                  {chartCount}
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Total charts
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  {activeChartCount} active · {draftChartCount} draft
                </Text>
              </BlockStack>
            </Card>

            <Card>
              <BlockStack gap="100">
                <Text as="h2" variant="headingXl" fontWeight="bold">
                  {activeChartCount}
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Published charts
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Visible on storefront
                </Text>
              </BlockStack>
            </Card>

            <Card>
              <BlockStack gap="100">
                <Text as="h2" variant="headingXl" fontWeight="bold">
                  {monthlyViews}x
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Views — current month
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Last 30 days
                </Text>
              </BlockStack>
            </Card>

            <Card>
              <BlockStack gap="100">
                <Text as="h2" variant="headingXl" fontWeight="bold">
                  {totalRecommendations}
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  AI recommendations
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  {plan.limits.aiRecommender ? "Active" : "Upgrade to unlock"}
                </Text>
              </BlockStack>
            </Card>
          </InlineGrid>
        </Layout.Section>

        {/* ================================================================ */}
        {/* CTA BANNER — show size charts for all products                    */}
        {/* ================================================================ */}
        {chartCount === 0 && (
          <Layout.Section>
            <Banner tone="info" title="Show size charts for all your products">
              <BlockStack gap="400">
                <Text as="p" variant="bodyMd">
                  Help your customers easily find the right size for every
                  product. Reduce returns by up to 40%.
                </Text>
                <InlineStack gap="400">
                  <Button variant="primary" url="/app/size-charts">
                    Create chart
                  </Button>
                  <Button url="/app/pricing">View plans</Button>
                </InlineStack>
              </BlockStack>
            </Banner>
          </Layout.Section>
        )}

        {/* ================================================================ */}
        {/* RECENT SIZE CHARTS                                                */}
        {/* ================================================================ */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              {/* Section header */}
              <InlineStack align="space-between" blockAlign="center">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  {chartCount > 0
                    ? "Recent size charts"
                    : "Create your size chart!"}
                </Text>
                {chartCount > 0 && (
                  <Button variant="plain" url="/app/size-charts">
                    View all
                  </Button>
                )}
              </InlineStack>

              {recentCharts.length === 0 ? (
                /* Empty state */
                <BlockStack gap="400">
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Create various types of size charts, AI Size
                    Recommendations.
                  </Text>
                  <Button variant="primary" url="/app/size-charts">
                    Create a Size Chart
                  </Button>
                </BlockStack>
              ) : (
                /* Chart rows */
                <BlockStack gap="200">
                  {recentCharts.map((chart, index) => (
                    <Box key={chart.id}>
                      {index > 0 && <Divider />}
                      <Box paddingBlock="300">
                        <InlineStack align="space-between" blockAlign="center">
                          <BlockStack gap="100">
                            <Button
                              variant="plain"
                              url={`/app/size-charts/${chart.id}`}
                            >
                              {chart.name}
                            </Button>
                            <InlineStack gap="200" blockAlign="center">
                              <Badge tone="info">{chart.category}</Badge>
                              <Badge
                                tone={
                                  chart.status === "active"
                                    ? "success"
                                    : "enabled"
                                }
                              >
                                {chart.status === "active" ? "Active" : "Draft"}
                              </Badge>
                              <Text as="p" variant="bodyMd" tone="subdued">
                                {chart.assignmentCount > 0
                                  ? `${chart.assignmentCount} product${chart.assignmentCount > 1 ? "s" : ""}`
                                  : "No assignments"}
                              </Text>
                            </InlineStack>
                          </BlockStack>
                          <Text as="p" variant="bodyMd" tone="subdued">
                            {formatDate(chart.updatedAt)}
                          </Text>
                        </InlineStack>
                      </Box>
                    </Box>
                  ))}
                </BlockStack>
              )}
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* ================================================================ */}
        {/* ENABLE APP — app status                                           */}
        {/* ================================================================ */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <BlockStack gap="100">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  Enable app
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Keep the app active to display size charts on your store.
                </Text>
              </BlockStack>

              <Box
                padding="400"
                borderWidth="025"
                borderColor="border-subdued"
                borderRadius="200"
                background="bg-surface-secondary"
              >
                <InlineStack align="space-between" blockAlign="center">
                  <InlineStack gap="200" blockAlign="center">
                    <Text as="p" variant="bodyMd">
                      Theme App Extension
                    </Text>
                    <Badge tone="info">Required</Badge>
                  </InlineStack>
                  <Badge tone={activeChartCount > 0 ? "success" : "enabled"}>
                    {activeChartCount > 0 ? "Active" : "Inactive"}
                  </Badge>
                </InlineStack>
              </Box>

              <Box
                padding="400"
                borderWidth="025"
                borderColor="border-subdued"
                borderRadius="200"
                background="bg-surface-secondary"
              >
                <InlineStack align="space-between" blockAlign="center">
                  <InlineStack gap="200" blockAlign="center">
                    <Text as="p" variant="bodyMd">
                      App Block
                    </Text>
                    <Badge tone="enabled">Optional</Badge>
                  </InlineStack>
                  <Badge tone={activeChartCount > 0 ? "success" : "enabled"}>
                    {activeChartCount > 0 ? "Active" : "Inactive"}
                  </Badge>
                </InlineStack>
              </Box>
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* ================================================================ */}
        {/* ASIDE — Plan & Usage                                              */}
        {/* ================================================================ */}
        <Layout.Section variant="oneThird">
          <BlockStack gap="400">
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  Your plan
                </Text>

                <InlineStack gap="200" blockAlign="center">
                  <Badge tone={isFreePlan ? "enabled" : "success"}>
                    {plan.name}
                  </Badge>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    {plan.price === 0 ? "Free" : `$${plan.price}/mo`}
                  </Text>
                </InlineStack>

                {isFreePlan && maxCharts > 0 && (
                  <BlockStack gap="100">
                    <Text as="p" variant="bodyMd" tone="subdued">
                      {chartCount} / {maxCharts} charts used
                    </Text>
                    <ProgressBar
                      progress={chartUsagePct}
                      tone={chartCount >= maxCharts ? "critical" : "highlight"}
                      size="small"
                    />
                  </BlockStack>
                )}

                <List>
                  {plan.features.slice(0, 4).map((f, i) => (
                    <List.Item key={i}>{f}</List.Item>
                  ))}
                </List>

                {isFreePlan && (
                  <Button url="/app/pricing" variant="primary">
                    Upgrade plan
                  </Button>
                )}
              </BlockStack>
            </Card>

            {/* ============================================================ */}
            {/* Quick links                                                    */}
            {/* ============================================================ */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  Quick links
                </Text>
                <List>
                  <List.Item>
                    <Button variant="plain" url="/app/size-charts">
                      Size Charts
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button variant="plain" url="/app/widget">
                      Widget Appearance
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button variant="plain" url="/app/recommender">
                      AI Recommender
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button variant="plain" url="/app/analytics">
                      Analytics
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button variant="plain" url="/app/settings">
                      Settings
                    </Button>
                  </List.Item>
                </List>
              </BlockStack>
            </Card>

            {/* ============================================================ */}
            {/* Help & Resources                                               */}
            {/* ============================================================ */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">
                  Need help?
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  We respond within 2 hours.
                </Text>
                <List>
                  <List.Item>
                    <Button variant="plain" url="mailto:support@sizechart.app">
                      Email support
                    </Button>
                  </List.Item>
                  <List.Item>
                    <Button variant="plain" url="/app/settings">
                      App settings
                    </Button>
                  </List.Item>
                </List>
                {plan.limits.prioritySupport && (
                  <Badge tone="success">Priority support</Badge>
                )}
              </BlockStack>
            </Card>
          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

